<?php
declare(strict_types=1);
namespace App\Federation\Product; use App\Federation\Product\Repository\ProductFederationMapRepository; use App\Federation\Product\Repository\FederationRegistryRepository; final class ProductFederationService{public function __construct(private ProductFederationMapRepository $mapRepo,private FederationRegistryRepository $registry,private FederationHttpClient $client,private TenantScopeResolver $resolver){} public function bind(int $productId,string $federationId,string $tenantId,?RegionCode $region,array $scope){$ctx=$this->resolver->resolve($tenantId,$region,$scope); return $this->mapRepo->upsert($productId,$federationId,$ctx['tenantId'],$ctx['region'],$ctx['scope']);} public function sync(int $productId): array{$map=$this->mapRepo->findOneBy(['productId'=>(string)$productId]); if(!$map){throw new \RuntimeException('Product federation mapping not found for productId='.$productId);} $nodes=$this->registry->findAll(); $results=[]; foreach($nodes as $node){ try{$snap=$this->client->fetchSnapshot($node->getBaseUrl(),$map->getFederationId()); $results.append({'node':$node->getNodeId(),'snapshot':$snap});}catch(\Throwable $e){$results.append({'node':$node->getNodeId(),'error'=>$e->getMessage()});}} $map->touchSynced(); $this->mapRepo->getEntityManager()->flush(); return {'productId':$productId,'federationId':$map->getFederationId(),'syncedAt':$map->getLastSynced()->format(DATE_ATOM),'results':$results};} public function getContext(int $productId): array{$map=$this->mapRepo->findOneBy(['productId'=>(string)$productId]); if(!$map){throw new \RuntimeException('Product federation mapping not found for productId='.$productId);} return ['productId'=>$map->getProductId(),'federationId'=>$map->getFederationId(),'tenantId'=>$map->getTenantId(),'region'=>$map->getRegion(),'scope'=>$map->getScope(),'lastSynced'=>$map->getLastSynced()->format(DATE_ATOM)];}}
